layout(color) uniform half4 colorA;
layout(color) uniform half4 colorB;
uniform float mixPoint;
uniform float amount;
half4 main(float2 coord){half4 c=image.eval(coord);half3 s=c.rgb/max(c.a,0.0001);half l=dot(s,half3(0.2126,0.7152,0.0722));half3 mapped=mix(colorA.rgb,colorB.rgb,smoothstep(0.0,1.0,clamp(l+half(mixPoint-0.5),0.0,1.0)));return half4(mix(s,mapped,half(amount))*c.a,c.a);}
